type HttpMethod = 'get' | 'post' | 'put' | 'patch' | 'delete';

type OpenApiSchema = Record<string, unknown>;

interface EndpointDefinition {
  method: HttpMethod;
  path: string;
  tag: string;
  operationId: string;
  summary: string;
  description: string;
  audience?: 'public' | 'user' | 'developer' | 'admin' | 'machine';
  requiredRole?: string;
  public?: boolean;
  security?: Array<Record<string, never[]>>;
  query?: Array<{ name: string; description: string; schema?: OpenApiSchema; required?: boolean }>;
  headers?: Array<{ name: string; description: string; schema?: OpenApiSchema; required?: boolean }>;
  body?: OpenApiSchema;
  bodyDescription?: string;
  bodyRequired?: boolean;
  successStatus?: number;
  successDescription?: string;
  response?: OpenApiSchema;
  responseContentType?: string;
  errors?: number[];
  deprecated?: boolean;
}

const schemaRef = (name: string): OpenApiSchema => ({ $ref: `#/components/schemas/${name}` });
const arrayOf = (items: OpenApiSchema): OpenApiSchema => ({ type: 'array', items });
const pageOf = (items: OpenApiSchema): OpenApiSchema => ({
  type: 'object',
  required: ['items'],
  properties: {
    items: arrayOf(items),
    nextCursor: { type: 'string', nullable: true },
    total: { type: 'integer', minimum: 0, nullable: true },
  },
});

const idParameter = (name: string): OpenApiSchema => ({
  name,
  in: 'path',
  required: true,
  description: `${name} path identifier.`,
  schema: /^(id|tagId|backendId|agentId)$/.test(name)
    ? { type: 'integer', minimum: 1 }
    : { type: 'string', minLength: 1 },
});

function pathParameters(path: string): OpenApiSchema[] {
  return [...path.matchAll(/\{([^}]+)\}/g)].map(match => idParameter(match[1]!));
}

