const responseDescriptions: Record<number, string> = {
  400: 'Invalid request.',
  401: 'Authentication is missing or invalid.',
  403: 'The authenticated identity lacks the required role, permission, scope or assurance.',
  404: 'The requested resource was not found in the authorized workspace.',
  409: 'Current state, revision or idempotency constraints conflict with the request.',
  413: 'The request exceeds a documented size limit.',
  422: 'The request is syntactically valid but violates the resource contract.',
  429: 'Rate limit exceeded.',
  500: 'Unexpected Argus error. The response includes a request identifier.',
  502: 'An upstream provider or runtime failed.',
  503: 'A required dependency or feature is unavailable.',
};

function buildResponses(definition: EndpointDefinition): Record<string, unknown> {
  const successStatus = definition.successStatus ?? 200;
  const contentType = definition.responseContentType ?? 'application/json';
  const responses: Record<string, unknown> = {
    [successStatus]: {
      description: definition.successDescription ?? 'Successful response.',
      ...(definition.response ? { content: { [contentType]: { schema: definition.response } } } : {}),
    },
  };
  for (const status of definition.errors ?? []) {
    responses[String(status)] = {
      description: responseDescriptions[status] ?? 'Error response.',
      content: { 'application/json': { schema: schemaRef('Error') } },
    };
  }
  return responses;
}

function buildOperation(definition: EndpointDefinition): Record<string, unknown> {
  const parameters = [
    ...pathParameters(definition.path),
    ...(definition.headers ?? []).map(parameter => ({ ...parameter,in:'header' })),
    ...(definition.query ?? []).map(parameter => ({
      name: parameter.name,
      in: 'query',
      required: parameter.required ?? false,
      description: parameter.description,
      schema: parameter.schema ?? { type: 'string' },
    })),
  ];
  return {
    tags: [definition.tag],
    operationId: definition.operationId,
    summary: definition.summary,
    description: definition.description,
    ...(parameters.length > 0 ? { parameters } : {}),
    ...(definition.body ? {
      requestBody: {
        required: definition.bodyRequired ?? true,
        description: definition.bodyDescription,
        content: {
          [definition.bodyDescription?.startsWith('multipart/') ? 'multipart/form-data' : 'application/json']: {
            schema: definition.body,
          },
        },
      },
    } : {}),
    responses: buildResponses(definition),
    security: definition.public ? [] : definition.security ?? apiSecurity,
    deprecated: definition.deprecated ?? false,
    'x-argus-audience': definition.audience ?? 'user',
    ...(definition.requiredRole ? { 'x-argus-required-role': definition.requiredRole } : {}),
  };
}

function buildPaths(): Record<string, Record<string, unknown>> {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const definition of endpoints) {
    paths[definition.path] ??= {};
    paths[definition.path]![definition.method] = buildOperation(definition);
  }
  return paths;
}

